// 1. RFID Card Database (ข้อย่อย 1ข & 3ก)
global.set("rfid_db", {
    "CARD_ADMIN": { name: "Administrator", allowed_floors: Array.from({length: 20}, (_, i) => i + 1) },
    "CARD_USER1": { name: "Engineering Staff", allowed_floors: [1, 2, 3, 4, 16] },
    "CARD_GUEST": { name: "Visitor", allowed_floors: [1, 2] }
});

// 2. Initial Elevator States as specified in Exam Problem 3(b)
// 2s per floor, 10s stop
global.set("cars", {
    "A": { current: 2, target: 2, dir: "UP", stops: [9, 16], load: 50, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() },
    "B": { current: 12, target: 12, dir: "DOWN", stops: [6, 1], load: 30, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() },
    "C": { current: 3, target: 3, dir: "UP", stops: [5], load: 90, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() },
    "D": { current: 1, target: 1, dir: "IDLE", stops: [], load: 0, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() - 6000 }
});

// 3. Hall Unit State Machine: IDLE, AUTH_PENDING, WAITING_TARGET, DISPATCHED
flow.set("hall_state", {
    status: "IDLE",
    card_id: null,
    allowed_floors: [],
    from_floor: 4,
    timer: 0
});

global.set("system_mode", "NORMAL");
return { payload: "SYSTEM INITIALIZED" };

let hall = flow.get("hall_state") || { status: "IDLE", card_id: "CARD_USER1", allowed_floors: [], from_floor: 4, target_floor: 16, timer: 0 };
const rfid_db = global.get("rfid_db") || {};
const mode = global.get("system_mode") || "NORMAL";

// Check fire emergency
if (mode === "FIRE_ALARM") {
    hall.status = "IDLE";
    flow.set("hall_state", hall);
    return [
        { payload: "<div style='color:red; font-weight:bold;'>[EMERGENCY] FIRE ALARM: OUT OF SERVICE</div>" },
        null
    ];
}

if (msg.topic === "set_from_floor") {
    hall.from_floor = Number(msg.payload);
}
if (msg.topic === "set_badge") {
    hall.card_id = String(msg.payload);
}
if (msg.topic === "set_target_floor") {
    hall.target_floor = Number(msg.payload);
}

// 1. EVENT: TAP RFID BADGE (Protocol Message 1: AUTH_REQ)
if (msg.topic === "tap_card") {
    const user = rfid_db[hall.card_id];
    if (!user) {
        hall.status = "IDLE";
        flow.set("hall_state", hall);
        return [
            { payload: "<div style='color:red;'>[AUTH REJECTED] CARD NOT FOUND</div>" },
            null
        ];
    }

    // Check if card has access to current floor
    if (!user.allowed_floors.includes(hall.from_floor)) {
        hall.status = "IDLE";
        flow.set("hall_state", hall);
        return [
            { payload: `<div style='color:red;'>[ACCESS DENIED] NO PERMISSION ON FLOOR ${hall.from_floor}</div>` },
            null
        ];
    }

    // AUTH OK: Start 10-second window (ข้อย่อย 2ค & 3ค)
    hall.status = "WAITING_TARGET";
    hall.allowed_floors = user.allowed_floors;
    hall.timer = 10;
    flow.set("hall_state", hall);

    const authOkMsg = `
    <div style="border:1px solid #16a34a; background:#f0fdf4; padding:8px; border-radius:4px;">
      <div style="color:#15803d; font-weight:bold;">[AUTH ACCEPTED] USER: ${user.name}</div>
      <div style="color:#374151; font-size:12px;">PLEASE SELECT TARGET FLOOR WITHIN: <b>${hall.timer}s</b></div>
    </div>`;
    return [{ payload: authOkMsg }, null];
}

// 2. EVENT: SUBMIT TARGET FLOOR (Protocol Message 3: CALL_REQ)
if (msg.topic === "submit_target") {
    if (hall.status !== "WAITING_TARGET") {
        return [
            { payload: "<div style='color:orange;'>[WARNING] PLEASE TAP RFID BADGE FIRST</div>" },
            null
        ];
    }

    // Verify destination permission
    if (!hall.allowed_floors.includes(hall.target_floor)) {
        return [
            { payload: `<div style='color:red;'>[TARGET DENIED] CARD NOT PERMITTED FOR FLOOR ${hall.target_floor}</div>` },
            null
        ];
    }

    // Forward request to Dispatch Engine
    hall.status = "DISPATCHED";
    hall.timer = 0;
    flow.set("hall_state", hall);

    const callPayload = {
        from_floor: hall.from_floor,
        target_floor: hall.target_floor,
        card_id: hall.card_id
    };

    return [
        { payload: `<div style='color:blue;'>[REQUEST SENT] DISPATCHING FOR FLOOR ${hall.target_floor}...</div>` },
        { topic: "elevator/hall/call_req", payload: callPayload }
    ];
}

// 3. EVENT: 1-SECOND TICK FOR 10s TIMEOUT
if (msg.topic === "timer_tick") {
    if (hall.status === "WAITING_TARGET" && hall.timer > 0) {
        hall.timer -= 1;
        flow.set("hall_state", hall);
        if (hall.timer === 0) {
            hall.status = "IDLE";
            flow.set("hall_state", hall);
            return [
                { payload: "<div style='color:red;'>[TIMEOUT] 10 SECONDS EXPIRED. TRANSACTION RESET.</div>" },
                null
            ];
        } else {
            return [
                { payload: `
                <div style="border:1px solid #16a34a; background:#f0fdf4; padding:8px; border-radius:4px;">
                  <div style="color:#15803d; font-weight:bold;">[AUTH ACCEPTED] SELECT FLOOR</div>
                  <div style="color:#374151; font-size:12px;">TIME REMAINING: <b>${hall.timer}s</b></div>
                </div>` },
                null
            ];
        }
    }
}

flow.set("hall_state", hall);
return null;

// Parse Input (WS JSON or MQTT Payload)
let raw = msg.payload;
if (typeof raw === "string") {
    try { raw = JSON.parse(raw); } catch(e) {}
}
const topic = msg.topic || "";
// 1. Handle Fire Alarm via WS or MQTT (elevator/safety/fire_alarm)
if (topic === "elevator/safety/fire_alarm" || (raw && (raw.topic === "fire_alarm" || raw.action === "fire_alarm" || raw.action === "cancel_fire"))) {
    const isCancel = (raw === false || raw === "false" || (raw && (raw.fire === false || raw.payload === false || raw.action === "cancel_fire")));
    if (isCancel) {
        global.set("system_mode", "NORMAL");
        let cars = global.get("cars") || {};
        cars["A"] = { current: 2, target: 2, dir: "UP", stops: [9, 16], load: 50, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() };
        cars["B"] = { current: 12, target: 12, dir: "DOWN", stops: [6, 1], load: 30, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() };
        cars["C"] = { current: 3, target: 3, dir: "UP", stops: [5], load: 90, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() };
        cars["D"] = { current: 1, target: 1, dir: "IDLE", stops: [], load: 0, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() - 6000 };
        global.set("cars", cars);
        const cancelRes = { status: "RESET_OK", message: "FIRE ALARM CANCELLED" };
        return [
            { payload: JSON.stringify(cancelRes), topic: "elevator/hall/assign" },
            { payload: "<div style='color:green; font-weight:bold;'>[ระบบปกติ] ยกเลิกสัญญาณเพลิงไหม้แล้ว</div>" },
            null
        ];
    } else {
        global.set("system_mode", "FIRE_ALARM");
        let cars = global.get("cars") || {};
        for (let id in cars) {
            cars[id].stops = [1];
            cars[id].dir = cars[id].current > 1 ? "DOWN" : "IDLE";
            cars[id].door = "CLOSED";
        }
        global.set("cars", cars);
        const fireRes = { status: "EMERGENCY", message: "FIRE ALARM ACTIVE" };
        return [
            { payload: JSON.stringify(fireRes), topic: "elevator/hall/assign" },
            { payload: "<div style='color:red; font-weight:bold; font-size:16px;'>[ฉุกเฉิน] ระบบแจ้งเตือนเหตุเพลิงไหม้ ลิฟต์งดให้บริการ</div>" },
            null
        ];
    }
}
// 2. Handle System Reset via WS or MQTT (elevator/system/reset)
if (topic === "elevator/system/reset" || (raw && (raw.topic === "reset_system" || raw.action === "reset_system"))) {
    global.set("system_mode", "NORMAL");
    let cars = global.get("cars") || {};
    cars["A"] = { current: 2, target: 2, dir: "UP", stops: [9, 16], load: 50, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() };
    cars["B"] = { current: 12, target: 12, dir: "DOWN", stops: [6, 1], load: 30, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() };
    cars["C"] = { current: 3, target: 3, dir: "UP", stops: [5], load: 90, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() };
    cars["D"] = { current: 1, target: 1, dir: "IDLE", stops: [], load: 0, door: "CLOSED", state: "IDLE", timer: 0, last_hb: Date.now() - 6000 };
    global.set("cars", cars);
    const resetRes = { status: "RESET_OK", message: "SYSTEM NORMALIZED" };
    return [
        { payload: JSON.stringify(resetRes), topic: "elevator/hall/assign" },
        { payload: "<div style='color:green; font-weight:bold;'>[ระบบปกติ] รีเซ็ตสถานะลิฟต์เรียบร้อย</div>" },
        null
    ];
}
// 3. Extract Floor Call Request (from WS payload or MQTT elevator/hall/{floor}/call_req)
let fromFloor = (raw && raw.from_floor) ? Number(raw.from_floor) : null;
if (!fromFloor && topic.includes("/hall/")) {
    const parts = topic.split("/"); const fromPart = parts[2]; if (fromPart && !isNaN(fromPart)) fromFloor = Number(fromPart);
}
if (!fromFloor) fromFloor = 4;
const req = {
    from_floor: fromFloor,
    target_floor: (raw && raw.target_floor) ? Number(raw.target_floor) : 16,
    card_id: String((raw && raw.card_id) ? raw.card_id : "CARD_USER1")
};
let cars = global.get("cars") || {};
const mode = global.get("system_mode") || "NORMAL";
if (mode === "FIRE_ALARM") {
    const fireRes = { status: "EMERGENCY", message: "FIRE ALARM ACTIVE" };
    return [
        { payload: JSON.stringify(fireRes), topic: "elevator/hall/" + req.from_floor + "/assign" },
        { payload: "<div style='color:red; font-weight:bold; font-size:16px;'>[ฉุกเฉิน] ระบบแจ้งเตือนเหตุเพลิงไหม้ ลิฟต์งดให้บริการ</div>" },
        null
    ];
}
// Validation 1: Origin and Target floor cannot be identical
if (req.from_floor === req.target_floor) {
    const errRes = { status: "DENIED", message: "INVALID: ORIGIN AND TARGET FLOOR CANNOT BE IDENTICAL" };
    return [
        { payload: JSON.stringify(errRes), topic: "elevator/hall/" + req.from_floor + "/assign" },
        { payload: "<div style='color:red;'>[DENIED] Origin and target floors must be different</div>" },
        null
    ];
}
// Validation 2: Floor range must be 1 - 20
if (req.from_floor < 1 || req.from_floor > 20 || req.target_floor < 1 || req.target_floor > 20) {
    const errRes = { status: "DENIED", message: "INVALID: FLOOR NUMBER OUT OF BOUNDS (1-20)" };
    return [
        { payload: JSON.stringify(errRes), topic: "elevator/hall/" + req.from_floor + "/assign" },
        { payload: "<div style='color:red;'>[DENIED] Floor out of bounds (1-20)</div>" },
        null
    ];
}
// Validation 3: Check RFID DB permissions
const rfid_db = global.get("rfid_db") || {};
const user = rfid_db[req.card_id];
if (!user || !user.allowed_floors.includes(req.from_floor) || !user.allowed_floors.includes(req.target_floor)) {
    const denyRes = { status: "DENIED", message: "PERMISSION DENIED: CARD NOT AUTHORIZED FOR SPECIFIED FLOORS" };
    return [
        { payload: JSON.stringify(denyRes), topic: "elevator/hall/" + req.from_floor + "/assign" },
        { payload: "<div style='color:red;'>[DENIED] Card unauthorized for specified floors</div>" },
        null
    ];
}
const MOVE_TIME = 2; // 2 วินาทีต่อชั้น
const STOP_TIME = 10; // 10 วินาทีต่อการจอดรับ-ส่ง
let selectedCar = null;
let minCost = Infinity;
const reqDir = req.target_floor > req.from_floor ? "UP" : "DOWN";
for (let id of ["A", "B", "C", "D"]) {
    let car = cars[id];
    let hbSec = (Date.now() - car.last_hb) / 1000;
    // กฎที่ 1: ตัดสิทธิ์หากขาด Heartbeat เกิน 3 วินาที (ตัดลิฟต์ D)
    if (hbSec > 3) continue;
    // กฎที่ 2: ตัดสิทธิ์หากน้ำหนักบรรทุกเกิน 80% (ตัดลิฟต์ C)
    if (car.load > 80) continue;
    // คำนวณเวลาประเมิน (Cost) ตามทิศทางและระยะทาง
    let cost = Infinity;
    if (reqDir === "UP" && car.dir === "UP" && car.current <= req.from_floor) {
        let floors = req.from_floor - car.current;
        let stopsBefore = car.stops.filter(s => s < req.from_floor).length;
        cost = (floors * MOVE_TIME) + (stopsBefore * STOP_TIME);
    } else if (reqDir === "DOWN" && car.dir === "DOWN" && car.current >= req.from_floor) {
        let floors = car.current - req.from_floor;
        let stopsBefore = car.stops.filter(s => s > req.from_floor).length;
        cost = (floors * MOVE_TIME) + (stopsBefore * STOP_TIME);
    } else if (car.dir === "IDLE" || car.dir === "-") {
        cost = Math.abs(car.current - req.from_floor) * MOVE_TIME;
    } else {
        cost = 100; // วิ่งคนละทิศทาง กำหนดโทษเวลา
    }
    if (cost < minCost) {
        minCost = cost;
        selectedCar = id;
    }
}
if (!selectedCar) {
    const unavail = { status: "UNAVAILABLE", message: "NO ELEVATOR AVAILABLE" };
    return [
        { payload: JSON.stringify(unavail), topic: "elevator/hall/" + req.from_floor + "/assign" },
        { payload: "<div style='color:red; font-weight:bold;'>[ขออภัย] ไม่มีลิฟต์พร้อมให้บริการในขณะนี้</div>" },
        null
    ];
}
// อัปเดตคิวรับส่งตามทิศทางการเคลื่อนที่
if (!cars[selectedCar].stops.includes(req.from_floor)) cars[selectedCar].stops.push(req.from_floor);
if (!cars[selectedCar].stops.includes(req.target_floor)) cars[selectedCar].stops.push(req.target_floor);
if (cars[selectedCar].dir === "DOWN") {
    cars[selectedCar].stops.sort((a, b) => b - a);
} else {
    cars[selectedCar].stops.sort((a, b) => a - b);
}
global.set("cars", cars);
const response = {
    status: "SUCCESS",
    assigned_car: selectedCar,
    from_floor: req.from_floor,
    target_floor: req.target_floor,
    cost: minCost,
    message: "PLEASE PROCEED TO ELEVATOR " + selectedCar
};
// แสดงผลลัพธ์ขั้นตอนที่ 3
const htmlDisplay = `
<div style="border:2px solid #16a34a; background:#f0fdf4; padding:12px; border-radius:6px; font-family:sans-serif;">
  <div style="color:#15803d; font-size:18px; font-weight:bold;">
    ขั้นตอนที่ 3: กรุณาไปขึ้นลิฟต์ช่อง [ CAR - ${selectedCar} ]
  </div>
  <div style="color:#1f2937; font-size:13px; margin-top:8px; line-height:1.6;">
    - <b>ชั้นต้นทาง:</b> ชั้น ${req.from_floor} | <b>ชั้นปลายทาง:</b> ชั้น ${req.target_floor}<br>
    - <b>เวลารอลิฟต์ประมาณ:</b> <span style="color:#2563eb; font-weight:bold; font-size:14px;">${minCost} วินาที</span>
  </div>
</div>`;
return [
    { payload: JSON.stringify(response), topic: "elevator/hall/" + req.from_floor + "/assign" }, // Out 1: WebSocket & MQTT Hall Assign
    { payload: htmlDisplay },                                                                   // Out 2: Hall Unit Display
    { topic: "elevator/car/" + selectedCar + "/command", payload: JSON.stringify({ car: selectedCar, add_stops: [req.from_floor, req.target_floor] }) } // Out 3: Physics Loop & MQTT Car Command
];

let cars = global.get("cars") || {};
const now = Date.now();
const mode = global.get("system_mode") || "NORMAL";

// Keep active heartbeats for A, B, C (Keep D offline as in Exam Problem 3b)
if (cars["A"]) cars["A"].last_hb = now;
if (cars["B"]) cars["B"].last_hb = now;
if (cars["C"]) cars["C"].last_hb = now;

// Physics loop for each car
for (let id of ["A", "B", "C"]) {
    let car = cars[id];
    if (!car) continue;

    // Safety Chain: If fire mode, target is floor 1
    if (mode === "FIRE_ALARM") {
        car.stops = [];
        if (car.current > 1) {
            car.timer = (car.timer || 0) + 1;
            if (car.timer >= 2) { // 2 seconds per floor
                car.current -= 1;
                car.current = Math.max(1, car.current);
                car.timer = 0;
            }
            car.dir = "DOWN";
            car.door = "CLOSED";
        } else {
            car.current = 1;
            car.dir = "IDLE";
            car.door = "OPEN";
            car.timer = 0;
        }
        continue;
    }

    // Normal destination dispatch service
    if (car.stops && car.stops.length > 0) {
        let nextStop = car.stops[0];

        if (car.current === nextStop) {
            // Arrived at destination: Door open for 10 seconds
            car.state = "STOPPED";
            car.door = "OPEN";
            car.timer = (car.timer || 0) + 1;
            if (car.timer >= 10) { // 10s passenger transfer
                car.stops.shift();
                car.timer = 0;
                car.door = "CLOSED";
                car.state = "IDLE";
            }
        } else {
            // Travelling: 2 seconds per floor
            car.state = "MOVING";
            car.door = "CLOSED";
            car.timer = (car.timer || 0) + 1;
            if (car.timer >= 2) {
                if (car.current < nextStop) {
                    car.current += 1;
                    car.dir = "UP";
                } else if (car.current > nextStop) {
                    car.current -= 1;
                    car.dir = "DOWN";
                }
                car.current = Math.max(1, Math.min(20, car.current));
                car.timer = 0;
            }
        }
    } else {
        car.dir = "IDLE";
        car.state = "IDLE";
        car.door = "CLOSED";
        car.timer = 0;
    }
}

global.set("cars", cars);

// Prepare telemetry message for MQTT and Status Table
msg.payload = JSON.stringify(cars);
msg.topic = "elevator/telemetry/cars";
return msg;

const cars = global.get("cars") || {};
const now = Date.now();
const mode = global.get("system_mode") || "NORMAL";

let rows = "";
for (let id of ["A", "B", "C", "D"]) {
    let car = cars[id];
    let hbSec = ((now - car.last_hb) / 1000).toFixed(1);
    let isOffline = hbSec > 3;
    let isOverload = car.load > 80;

    let statusText = "NORMAL";
    let statusColor = "#16a34a"; // green

    if (isOffline) {
        statusText = `COMM ERROR (${hbSec}s)`;
        statusColor = "#dc2626"; // red
    } else if (isOverload) {
        statusText = "OVERLOAD (>80%)";
        statusColor = "#ea580c"; // orange
    } else if (car.state === "STOPPED") {
        statusText = `SERVICING (DOOR ${car.door})`;
        statusColor = "#2563eb"; // blue
    }

    let stopsStr = (car.stops && car.stops.length > 0) ? car.stops.join(", ") : "-";

    rows += `
    <tr style="border-bottom: 1px solid #e5e7eb;">
      <td style="padding: 6px; text-align: center; font-weight: bold;">${id}</td>
      <td style="padding: 6px; text-align: center; font-weight: bold; color: #1e3a8a;">Floor ${car.current}</td>
      <td style="padding: 6px; text-align: center;">${car.dir}</td>
      <td style="padding: 6px; text-align: center;">${car.door}</td>
      <td style="padding: 6px; text-align: center;">${stopsStr}</td>
      <td style="padding: 6px; text-align: center;">${car.load}%</td>
      <td style="padding: 6px; text-align: center; color: ${statusColor}; font-weight: bold;">${statusText}</td>
    </tr>
    `;
}

let modeText = (mode === "FIRE_ALARM")
    ? "<div style='color: red; font-weight: bold; margin-bottom: 8px;'>[STATUS: FIRE ALARM - EMERGENCY EVACUATION TO FLOOR 1]</div>"
    : "<div style='color: green; font-weight: bold; margin-bottom: 8px;'>[STATUS: SYSTEM NORMAL]</div>";

let tableHtml = `
<div style="font-family: Arial, sans-serif; font-size: 13px;">
  ${modeText}
  <table style="width: 100%; border-collapse: collapse;">
    <thead>
      <tr style="background: #f3f4f6; border-bottom: 2px solid #d1d5db;">
        <th style="padding: 6px;">Car</th>
        <th style="padding: 6px;">Floor</th>
        <th style="padding: 6px;">Direction</th>
        <th style="padding: 6px;">Door</th>
        <th style="padding: 6px;">Queue</th>
        <th style="padding: 6px;">Load</th>
        <th style="padding: 6px;">Telemetry</th>
      </tr>
    </thead>
    <tbody>
      ${rows}
    </tbody>
  </table>
</div>
`;

return { payload: tableHtml };

const fire = (msg.payload === true || msg.payload === "true");
let cars = global.get("cars") || {};

if (fire) {
    global.set("system_mode", "FIRE_ALARM");
    for (let id in cars) {
        cars[id].stops = [1];
        cars[id].dir = cars[id].current > 1 ? "DOWN" : "IDLE";
        cars[id].door = "CLOSED";
    }
} else {
    global.set("system_mode", "NORMAL");
}

global.set("cars", cars);
return { payload: "FIRE STATE UPDATED" };
